import os,struct,subprocess,sys
bb=sys.argv[1]; kind=sys.argv[2]
def w(name,data):
 open(name,"wb").write(data)
if kind=="garbage": w("garbage.bin",b"not a font at all")
elif kind=="psf1": w("font.bin",bytes([0x36,4,0,16])+bytes(256*16))
elif kind=="psf2":
 w("font.bin",bytes([0x72,0xb5,0x4a,0x86])+struct.pack("<7I",0,32,0,256,16,16,8)+bytes(256*16))
elif kind=="badsize": w("font.bin",bytes([0x36,4,0,0])+bytes(256))
elif kind=="h33": w("font.bin",bytes([0x36,4,0,33])+bytes(256*33))
elif kind=="mode6": w("font.bin",bytes([0x36,4,6,16])+bytes(256*16))
elif kind=="ver9":
 w("font.bin",bytes([0x72,0xb5,0x4a,0x86])+struct.pack("<7I",9,32,0,256,16,16,8)+bytes(256*16))
elif kind=="short": w("font.bin",bytes([0x36,4,0,16])+bytes(100))
else: raise SystemExit(2)
name="garbage.bin" if kind=="garbage" else "font.bin"
r=subprocess.run([bb,"setfont","-C","/dev/null",name],stdout=subprocess.PIPE,stderr=subprocess.PIPE)
sys.stdout.buffer.write(r.stdout); sys.stderr.buffer.write(r.stderr); raise SystemExit(r.returncode)

